# -*- coding: utf-8 -*-
# Ikki marta bosib ishga tushiring (yoki: python tayyorla.py).
# Shu fayl turgan joyda "topshiriq3-solid" papkasini to'liq yaratadi.
import os
FILES = {
 "README.md": "# Topshiriq №3 (M3 + A3): SOLID tamoyillari va Refaktoring\n\n**Fan:** Dasturlash texnologiyalari  \n**Talaba:** Xamroyeva Gulruh  \n**Guruh:** 1-1DIM-24  \n**Til:** Java 11+\n\n## Loyiha tuzilmasi\n\n```\nsrc/\n├── vazifa1/   (SRP)  before/OrderManager.java, after/{Order,OrderItem,InvoiceService,EmailService}.java, Main.java\n├── vazifa2/   (OCP)  before/DiscountCalculator.java, after/{DiscountStrategy,NoDiscount,StudentDiscount,VeteranDiscount,SeasonalDiscount,LoyaltyDiscount,PriceCalculator}.java, Main.java\n└── vazifa3/   (DIP+ISP) before/NotificationService.java, after/{MessageSender,EmailSender,SmsSender,TelegramSender,NotificationService}.java, Main.java\n```\n\n## Ishga tushirish\n\n```bash\njavac -encoding UTF-8 -d out $(find src -name \"*.java\")\n\njava -cp out vazifa1.Main\njava -cp out vazifa2.Main\njava -cp out vazifa3.Main\n```\n\n## SOLID tamoyillari qo'llanishi\n\n| Tamoyil | Vazifa | Tavsif |\n|---------|--------|--------|\n| SRP | Vazifa 1 | OrderManager → Order + InvoiceService + EmailService |\n| OCP | Vazifa 2 | if/else → Strategy pattern, yangi tur qo'shish oson |\n| DIP | Vazifa 3 | NotificationService → MessageSender interfeysi |\n| ISP | Vazifa 3 | Katta interfeys o'rniga kichik MessageSender |\n",
 ".gitignore": "out/\n*.class\n*.iml\n.idea/\n",
 "src/vazifa2/Main.java": "package vazifa2;\n\nimport vazifa2.before.DiscountCalculator;\nimport vazifa2.after.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        double price = 1_000_000;\n\n        System.out.println(\"===== BEFORE: OCP buzilgan =====\");\n        DiscountCalculator calc = new DiscountCalculator();\n        for (String t : new String[]{\"NONE\", \"STUDENT\", \"VETERAN\", \"SEASONAL\"})\n            System.out.printf(\"%-9s: %,.0f%n\", t, calc.calculate(t, price));\n\n        System.out.println(\"\\n===== AFTER: OCP + Strategy =====\");\n        PriceCalculator pc = new PriceCalculator(new NoDiscount());\n        pc.calculate(price);\n        pc.setStrategy(new StudentDiscount());  pc.calculate(price);\n        pc.setStrategy(new VeteranDiscount());  pc.calculate(price);\n        pc.setStrategy(new SeasonalDiscount()); pc.calculate(price);\n        pc.setStrategy(new LoyaltyDiscount(5)); pc.calculate(price); // yangi tur\n    }\n}\n",
 "src/vazifa2/before/DiscountCalculator.java": "package vazifa2.before;\n\n/** BEFORE: OCP buzilgan - yangi tur qo'shilsa sinf o'zgaradi. */\npublic class DiscountCalculator {\n    public double calculate(String type, double price) {\n        if (type.equals(\"NONE\")) return price;\n        else if (type.equals(\"STUDENT\")) return price * 0.90;\n        else if (type.equals(\"VETERAN\")) return price * 0.85;\n        else if (type.equals(\"SEASONAL\")) return price * 0.80;\n        else throw new IllegalArgumentException(\"Noma'lum tur: \" + type);\n    }\n}\n",
 "src/vazifa2/after/PriceCalculator.java": "package vazifa2.after;\n\n/** OCP: bu sinf yangi strategiya qo'shilsa ham o'zgarmaydi. */\npublic class PriceCalculator {\n    private DiscountStrategy strategy;\n    public PriceCalculator(DiscountStrategy strategy) { this.strategy = strategy; }\n    public void setStrategy(DiscountStrategy strategy) { this.strategy = strategy; }\n    public double calculate(double originalPrice) {\n        double result = strategy.apply(originalPrice);\n        System.out.printf(\"%-32s: %,10.0f -> %,10.0f so'm%n\", strategy.getName(), originalPrice, result);\n        return result;\n    }\n}\n",
 "src/vazifa2/after/VeteranDiscount.java": "package vazifa2.after;\n\npublic class VeteranDiscount implements DiscountStrategy {\n    @Override public double apply(double price) { return price * 0.85; }\n    @Override public String getName() { return \"Faxriy chegirmasi (15%)\"; }\n}\n",
 "src/vazifa2/after/StudentDiscount.java": "package vazifa2.after;\n\npublic class StudentDiscount implements DiscountStrategy {\n    @Override public double apply(double price) { return price * 0.90; }\n    @Override public String getName() { return \"Talaba chegirmasi (10%)\"; }\n}\n",
 "src/vazifa2/after/SeasonalDiscount.java": "package vazifa2.after;\n\npublic class SeasonalDiscount implements DiscountStrategy {\n    @Override public double apply(double price) { return price * 0.80; }\n    @Override public String getName() { return \"Mavsumiy chegirma (20%)\"; }\n}\n",
 "src/vazifa2/after/LoyaltyDiscount.java": "package vazifa2.after;\n\n/** Yangi tur - mavjud kod o'zgarmadi! */\npublic class LoyaltyDiscount implements DiscountStrategy {\n    private final int years;\n    public LoyaltyDiscount(int yearsOfLoyalty) { this.years = yearsOfLoyalty; }\n    @Override public double apply(double price) {\n        double rate = Math.min(years * 0.02, 0.30); // har yil 2%, maksimum 30%\n        return price * (1 - rate);\n    }\n    @Override public String getName() { return \"Sodiqlik chegirmasi (\" + years + \" yil)\"; }\n}\n",
 "src/vazifa2/after/DiscountStrategy.java": "package vazifa2.after;\n\n/** OCP: chegirma strategiyasi interfeysi. */\npublic interface DiscountStrategy {\n    double apply(double price);\n    String getName();\n}\n",
 "src/vazifa2/after/NoDiscount.java": "package vazifa2.after;\n\npublic class NoDiscount implements DiscountStrategy {\n    @Override public double apply(double price) { return price * 1.00; }\n    @Override public String getName() { return \"Chegirmasiz\"; }\n}\n",
 "src/vazifa3/Main.java": "package vazifa3;\n\nimport vazifa3.after.*;\nimport java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(\"===== BEFORE: DIP buzilgan =====\");\n        new vazifa3.before.NotificationService().notify(\"EMAIL\", \"gulruh@mail.uz\", \"Salom!\");\n        new vazifa3.before.NotificationService().notify(\"SMS\", \"+998901234567\", \"Salom!\");\n\n        System.out.println(\"\\n===== AFTER: DIP + ISP =====\");\n        NotificationService svc = new NotificationService(\n            Arrays.asList(new EmailSender(), new SmsSender()));\n        svc.notifyAll(\"gulruh\", \"Topshiriq qabul qilindi\");\n\n        // Yangi kanal - NotificationService o'zgarmadi!\n        NotificationService svc2 = new NotificationService(\n            Arrays.asList(new EmailSender(), new SmsSender(), new TelegramSender()));\n        svc2.notifyAll(\"gulruh\", \"Yangi kanal qo'shildi\");\n    }\n}\n",
 "src/vazifa3/before/NotificationService.java": "package vazifa3.before;\n\n/** BEFORE: DIP buzilgan - konkret sinflarga qattiq bog'liq. */\npublic class NotificationService {\n    private final EmailSender email = new EmailSender();\n    private final SmsSender sms = new SmsSender();\n\n    public void notify(String channel, String to, String text) {\n        if (channel.equals(\"EMAIL\")) email.sendEmail(to, text);\n        else if (channel.equals(\"SMS\")) sms.sendSms(to, text);\n        else throw new IllegalArgumentException(\"Noma'lum kanal: \" + channel);\n    }\n\n    static class EmailSender { void sendEmail(String to, String t) { System.out.println(\"[EMAIL] \" + to + \": \" + t); } }\n    static class SmsSender   { void sendSms(String to, String t)   { System.out.println(\"[SMS] \" + to + \": \" + t); } }\n}\n",
 "src/vazifa3/after/SmsSender.java": "package vazifa3.after;\n\npublic class SmsSender implements MessageSender {\n    @Override public void send(String to, String text) {\n        System.out.println(\"[SMS] \" + to + \": \" + text);\n    }\n}\n",
 "src/vazifa3/after/EmailSender.java": "package vazifa3.after;\n\npublic class EmailSender implements MessageSender {\n    @Override public void send(String to, String text) {\n        System.out.println(\"[EMAIL] \" + to + \": \" + text);\n    }\n}\n",
 "src/vazifa3/after/TelegramSender.java": "package vazifa3.after;\n\npublic class TelegramSender implements MessageSender {\n    @Override public void send(String to, String text) {\n        System.out.println(\"[TELEGRAM] \" + to + \": \" + text);\n    }\n}\n",
 "src/vazifa3/after/MessageSender.java": "package vazifa3.after;\n\n/** ISP: kichik, aniq interfeys. */\npublic interface MessageSender {\n    void send(String to, String text);\n}\n",
 "src/vazifa3/after/NotificationService.java": "package vazifa3.after;\n\nimport java.util.List;\n\n/** DIP: konkret sinfga emas, MessageSender abstraksiyasiga bog'liq. */\npublic class NotificationService {\n    private final List<MessageSender> senders;\n    public NotificationService(List<MessageSender> senders) { this.senders = senders; }\n    public void notifyAll(String to, String text) {\n        for (MessageSender s : senders) s.send(to, text);\n    }\n}\n",
 "src/vazifa1/Main.java": "package vazifa1;\n\nimport vazifa1.before.OrderManager;\nimport vazifa1.after.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(\"===== BEFORE: God class =====\");\n        OrderManager om = new OrderManager(\"gulruh@mail.uz\");\n        om.addItem(\"Kitob\", 50_000);\n        om.addItem(\"Daftar\", 12_000);\n        om.sendInvoiceEmail();\n\n        System.out.println(\"\\n===== AFTER: SRP =====\");\n        Order order = new Order(\"gulruh@mail.uz\");\n        order.addItem(new OrderItem(\"Kitob\", 50_000));\n        order.addItem(new OrderItem(\"Daftar\", 12_000));\n        String invoice = new InvoiceService().generate(order);\n        new EmailService().send(order.getCustomerEmail(), invoice);\n    }\n}\n",
 "src/vazifa1/before/OrderManager.java": "package vazifa1.before;\n\nimport java.util.ArrayList;\nimport java.util.List;\n\n/** BEFORE: God class - SRP buzilgan (buyurtma + hisob-faktura + email). */\npublic class OrderManager {\n    private final List<String> names = new ArrayList<>();\n    private final List<Double> prices = new ArrayList<>();\n    private final String customerEmail;\n\n    public OrderManager(String customerEmail) { this.customerEmail = customerEmail; }\n\n    // 1) buyurtma logikasi\n    public void addItem(String name, double price) { names.add(name); prices.add(price); }\n    public double getTotal() { double s = 0; for (double p : prices) s += p; return s; }\n\n    // 2) hisob-faktura logikasi\n    public String generateInvoice() {\n        StringBuilder sb = new StringBuilder(\"HISOB-FAKTURA\\n\");\n        for (int i = 0; i < names.size(); i++)\n            sb.append(String.format(\"  %-12s %,10.0f so'm%n\", names.get(i), prices.get(i)));\n        sb.append(String.format(\"  JAMI: %,.0f so'm\", getTotal()));\n        return sb.toString();\n    }\n\n    // 3) email logikasi\n    public void sendInvoiceEmail() {\n        System.out.println(\"Email -> \" + customerEmail + \"\\n\" + generateInvoice());\n    }\n}\n",
 "src/vazifa1/after/EmailService.java": "package vazifa1.after;\n\n/** SRP: faqat email yuborish. */\npublic class EmailService {\n    public void send(String to, String body) {\n        System.out.println(\"Email -> \" + to + \"\\n\" + body);\n    }\n}\n",
 "src/vazifa1/after/InvoiceService.java": "package vazifa1.after;\n\n/** SRP: faqat hisob-faktura yaratish. */\npublic class InvoiceService {\n    public String generate(Order order) {\n        StringBuilder sb = new StringBuilder(\"HISOB-FAKTURA\\n\");\n        for (OrderItem i : order.getItems())\n            sb.append(String.format(\"  %-12s %,10.0f so'm%n\", i.getName(), i.getPrice()));\n        sb.append(String.format(\"  JAMI: %,.0f so'm\", order.getTotal()));\n        return sb.toString();\n    }\n}\n",
 "src/vazifa1/after/Order.java": "package vazifa1.after;\n\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\n\n/** SRP: faqat buyurtma (mahsulotlar va jami summa). */\npublic class Order {\n    private final String customerEmail;\n    private final List<OrderItem> items = new ArrayList<>();\n\n    public Order(String customerEmail) { this.customerEmail = customerEmail; }\n    public void addItem(OrderItem item) { items.add(item); }\n    public List<OrderItem> getItems() { return Collections.unmodifiableList(items); }\n    public String getCustomerEmail() { return customerEmail; }\n    public double getTotal() {\n        double sum = 0;\n        for (OrderItem i : items) sum += i.getPrice();\n        return sum;\n    }\n}\n",
 "src/vazifa1/after/OrderItem.java": "package vazifa1.after;\n\n/** SRP: faqat bitta mahsulot ma'lumoti. */\npublic class OrderItem {\n    private final String name;\n    private final double price;\n    public OrderItem(String name, double price) { this.name = name; this.price = price; }\n    public String getName() { return name; }\n    public double getPrice() { return price; }\n}\n"
}
base = os.path.join(os.path.dirname(os.path.abspath(__file__)), "topshiriq3-solid")
for rel, text in FILES.items():
    path = os.path.join(base, *rel.split("/"))
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
print("Tayyor! Papka:", base)
print("Fayllar soni:", len(FILES))
input("Yopish uchun Enter bosing...")
